# Convertendo para zstd

Antes do código, três pontos importantes:

- **A API do zstd é própria.** As funções centrais são `zstd_decompress()` (descompactar) e `zstd_compress()` (comprimir), além de `zstd_compress_bound(N)`, que retorna um **teto teórico** para o tamanho da saída (ótimo para pré-alocar memória).
- **Diferença conceitual:** o zlib manipula um *stream* deflate "raw"; o zstd trabalha com **frames completos** (tem mágica, flags, CRC, tabelas internas). Ou seja, o resultado de `zstd_compress` já é um arquivo/zstream zstd válido — `zstd_decompress` lê, valida e descompacta sozinho.
- A assinatura moderna (libzstd 0.18+) aceita nível de compressão e flags extras (usei `ZSTD_COMMON_FLAGS_DEFAULT`, que é 0). Se sua build for de outra versão, ajuste conforme seu `zstd.h`.

---

## 1) Descompactar (equivalente à sua `NormalUncompress`)

### 1a. Versão simples — requer buffer já com espaço suficiente

```c
int uncompress_zstd(uint8_t* dest, uint32_t* destLen,
                    const uint8_t* src, uint32_t srcLen,
                    unsigned level)
{
    if (srcLen == 0) return 0;

    uint32_t est;
    int r = zstd_decompress(dest, &est, src, srcLen, level,
                            ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;
    /* `est` agora contém o tamanho real dos dados descomprimidos */
    *destLen = est;
    return 0;
}
```

> Atenção: se `*destLen == 0`, a função recebe um buffer sem espaço e retorna `Z_BUF_ERROR` (assim como o inflate do zlib ignora silenciosamente com `avail_out == 0`). Por isso existe a versão "auto" abaixo.

### 1b. Versão robusta — cresce o buffer automaticamente (recomendada)

```c
#define BUFFER_EXPAND_LIMIT ((size_t)64 * 1024 * 1024)  /* 64 MiB; aumente se precisar */

int uncompress_zstd_auto(uint8_t* dest, uint32_t* destLen,
                         const uint8_t* src, uint32_t srcLen,
                         unsigned level)
{
    if (srcLen == 0) return 0;

    size_t maxOut = zstd_compress_bound((size_t)srcLen);   /* teto garantido */
    size_t cap    = (size_t)*destLen;
    uint8_t* buf  = (uint8_t*)dest;
    uint32_t est  = (uint32_t)cap;

    while (cap < maxOut) {
        size_t nxt;
        if (cap < maxOut / 2)         nxt = maxOut;         /* estima déficit grande */
        else                          nxt = (size_t)((size_t)cap * 2 + 1);
        if (nxt <= cap) break;       /* proteção contra overflow */
        uint8_t* tmp = (uint8_t*)realloc((uint8_t*)dest, nxt);
        if (!tmp) return -1;
        buf    = tmp;
        *destLen = (uint32_t)nxt;
        cap     = nxt;
        est     = (uint32_t)cap;    /* retenta com o buffer maior */
    }

    uint32_t outLen;
    int r = zstd_decompress(buf, &outLen, src, srcLen, level,
                            ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;

    *destLen = outLen;
    return 0;
}
```

---

## 2) Criar uma função de compressão para zstd

### 2a. Versão simples

```c
int compress_zstd(uint8_t* dest, uint32_t* destLen,
                  const uint8_t* src, uint32_t srcLen,
                  unsigned level)
{
    if (srcLen == 0) {
        /* entrada vazia ainda gera um frame mínimo; a própria API calcula */
        uint32_t est;
        int r = zstd_compress(dest, &est, NULL, 0, level,
                              ZSTD_COMMON_FLAGS_DEFAULT);
        if (r != Z_OK) return -1;
        *destLen = est;
        return 0;
    }

    size_t bound = zstd_compress_bound((size_t)srcLen);
    if ((size_t)*destLen < bound) return -1;   /* sem espaço suficiente */

    uint32_t est = (uint32_t)*destLen;
    int r = zstd_compress(dest, &est, src, srcLen, level,
                          ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;

    *destLen = est;
    return 0;
}
```

### 2b. Versão com expansão automática de buffer

```c
int compress_zstd_auto(uint8_t* dest, uint32_t* destLen,
                       const uint8_t* src, uint32_t srcLen,
                       unsigned level)
{
    if (srcLen == 0) {
        uint32_t est;
        int r = zstd_compress(dest, &est, NULL, 0, level,
                              ZSTD_COMMON_FLAGS_DEFAULT);
        if (r != Z_OK) return -1;
        *destLen = est;
        return 0;
    }

    size_t bound = zstd_compress_bound((size_t)srcLen);
    size_t cap   = (size_t)*destLen;
    uint8_t* buf = (uint8_t*)dest;
    uint32_t est = (uint32_t)cap;

    while (cap < bound) {
        size_t nxt;
        if (cap < bound / 2)      nxt = bound;      /* prever quase tudo */
        else                      nxt = (size_t)((size_t)cap * 2 + 1);
        if (nxt <= cap) break;
        uint8_t* tmp = (uint8_t*)realloc((uint8_t*)dest, nxt);
        if (!tmp) return -1;
        buf    = tmp;
        *destLen = (uint32_t)nxt;
        cap     = nxt;
        est     = (uint32_t)cap;
    }

    int r = zstd_compress(buf, &est, src, srcLen, level,
                          ZSTD_COMMON_FLAGS_DEFAULT);
    if (r == Z_BUF_ERROR) return -1;   /* improvável após crescer até `bound` */
    if (r != Z_OK) return -1;

    *destLen = est;
    return 0;
}
```

---

## 3) Streaming incremental (arquivos grandes / cópia em tempo real)

Para fluxos grandes, usa-se o contexto de streaming (`zstd_dctx_*` para descompactar). A lógica é sempre: **iniciar → alimentar blocos → finalizar**. As assinaturas abaixo variam levemente entre versões do libzstd — confirme no seu `zstd.h`.

### 3a. Descompactação incremental (exemplo completo)

```c
typedef struct {
    zstd_decompress_ctx* dc;
    uint8_t* dst;
    size_t cap;
    size_t pos;   /* offset de escrita dentro do buffer de saída */
} zstd_decomp_ctx_t;

/* Inicializa o contexto com um trecho inicial que cubra o primeiro bloco.
 * Se você não sabe o tamanho exato do primeiro bloco, passe um chunk razoável
 * (ex.: 1 MiB). */
static int zstd_decomp_new(zstd_decomp_ctx_t* d,
                           const uint8_t* first, uint32_t firstLen,
                           uint8_t* dst, size_t cap)
{
    d->dc = zstd_dctx_create(Zstd_compressionLevel_default);
    if (!d->dc) return -1;

    int r = zstd_dctx_start_decompress(d->dc, first, firstLen);
    if (r != Z_OK) { zstd_dctx_destroy(d->dc); return -1; }

    d->dst = dst; d->cap = cap; d->pos = 0;
    return 0;
}

/**
 * Processa pedaços da entrada até encher o buffer de saída.
 * AVANÇA A FONTE PELO TAMANHO DA SAÍDA RECEBIDA — não pelo tamanho do chunk.
 * Isso funciona em todos os modos (inclusive com dicionário, onde a saída
 * pode ser maior que a entrada consumida).
 */
static size_t zstd_decomp_fill(zstd_decomp_ctx_t* d,
                               const uint8_t* src, size_t srcLen,
                               uint8_t* out, size_t outCap)
{
    size_t written = 0;
    size_t pos     = 0;
    size_t chunk;
    uint32_t outLen;
    int r;

    while (pos < srcLen && written < outCap) {
        size_t remaining = srcLen - pos;
        chunk = (remaining < 65536ULL) ? remaining : 65536ULL;

        r = zstd_dctx_read(d->dc, out + written, &outLen,
                           src + pos, chunk);
        if (r != Z_OK) return 0;   /* erro de I/O */
        if (outLen == 0 && written == 0) return 0; /* nada foi produzido */

        written += outLen;
        pos     += outLen;         /* ← avance pela saída, não pelo chunk */
    }
    return written;
}

/* Depois de terminar toda a entrada: esvaziar pendências e finalizar. */
static int zstd_decomp_finish(zstd_decomp_ctx_t* d,
                              uint8_t** out, uint32_t* outLen)
{
    uint8_t* p = d->dst + d->pos;
    size_t len;
    int r;

    r = zstd_dctx_flush(d->dc, p, &len);          /* joga bloco(s) pendente(s) */
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;  /* precisaria de mais memória */
    p += (size_t)len;

    r = zstd_dctx_finish(d->dc, p, &len);         /* Z_STREAM_END = sucesso total */
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *out  = d->dst;
    *outLen = (uint32_t)(p - d->dst);
    return 0;
}

void zstd_decomp_destroy(zstd_decomp_ctx_t* d) { zstd_dctx_destroy(d->dc); }
```

**Exemplo de uso (consumir um arquivo comprimido):**

```c
int consume_arquivo(const uint8_t* file, size_t fileSize,
                    uint8_t** out, uint32_t* outLen)
{
    zstd_decomp_ctx_t dc;
    uint8_t* out = malloc(sizeof(uint8_t) * (fileSize + 64 * 1024 * 1024));
    if (!out) return -1;
    uint32_t total = 0;

    /* começa a leitura; precisa do primeiro bloco para validar o frame */
    int r = zstd_dctx_start_decompress(&dc, file, (uint32_t)min(fileSize, 1024 * 1024));
    if (r != Z_OK) { free(out); zstd_decomp_destroy(&dc); return -1; }

    size_t pos = 0;
    while (pos < fileSize) {
        size_t remaining = fileSize - pos;
        size_t chunk = (remaining < 65536ULL) ? remaining : 65536ULL;
        uint32_t outLen;
        r = zstd_dctx_read(dc.dc, out + (size_t)total, &outLen,
                           file + (size_t)pos, chunk);
        if (r != Z_OK) { free(out); zstd_decomp_destroy(&dc); return -1; }
        total += outLen;
        pos    += outLen;
    }

    r = zstd_decomp_finish(&dc, &out, &outLen);
    if (r != Z_OK && r != Z_STREAM_END) { free(out); zstd_decomp_destroy(&dc); return -1; }

    *out       = out;
    *outLen    = total + outLen;   /* o finish pode escrever mais bytes */
    return 0;
}
```

### 3b. Compressão incremental (esqueleto — confira as assinaturas em `zstd.h`)

```c
typedef struct {
    zstd_compress_ctx* ctx;
    uint8_t* dst;
    size_t cap;
    size_t pos;
} zstd_comp_ctx_t;

static int zstd_comp_new(zstd_comp_ctx_t* c, uint8_t* dst, size_t cap, unsigned level)
{
    c->ctx = zstd_create_compress(level);
    if (!c->ctx) return -1;
    int r = zstd_cctx_start_compress(c->ctx, dst, cap, 0);  /* 0 = flags padrão */
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;          /* falta espaço p/ iniciar */
    c->dst = dst; c->cap = cap; c->pos = 0;
    return 0;
}

static int zstd_comp_write(zstd_comp_ctx_t* c, const uint8_t* src, size_t srcLen,
                           size_t* totalOut)
{
    size_t written = 0;
    size_t pos     = 0;
    size_t remaining = srcLen;
    size_t chunk;
    size_t sz;
    int r;

    while (pos < remaining) {
        chunk = (remaining - pos < 65536ULL) ? (remaining - pos) : 65536ULL;
        r = zstd_cctx_compress(c->ctx, c->dst + written, &sz,
                               src + (size_t)pos, chunk, 0);
        if (r == Z_OK) {
            written += sz;
            pos     += chunk;      /* avança por inteiro; o contexto continua de onde parou */
        }
        else if (r == Z_BUF_ERROR) return -1;   /* cresça o buffer de saída e repita */
        else return -1;
    }

    /* flush do último bloco + finalização do frame */
    sz;
    r = zstd_cctx_flush(c->ctx, c->dst + written, &sz);
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;
    written += sz;

    r = zstd_cctx_finish(c->ctx, c->dst + written, &sz);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *totalOut = written;
    return 0;
}

void zstd_comp_destroy(zstd_comp_ctx_t* c) { zstd_cctx_destroy(c->ctx); }
```

---

## 4) Dicas práticas

- **Pré-alocação:** chame `zstd_compress_bound(N)` para saber o máximo possível de bytes de saída. Ideal para abrir arquivos cujo tamanho você conhece.
- **Erros comuns:** `Z_BUF_ERROR` = falta de espaço no buffer (refaça com buffer maior); `Z_ERROR`/`Z_DATA_ERROR` = frame corrompido/inválido (trate separadamente).
- **Multi-frame:** `zstd_decompress` aceita múltiplos frames em sequência, assim como gzip aceita vários .gz empilhados.
- **Razão lossy:** zstd é lossy; dependendo da entrada, a saída pode ficar bem maior que a entrada (por isso o `bound()` é indispensável).
- **Teste rápido:** gere com `zstd -tc arquivo.in` e valide com `zstd --test arquivo.out` ou `zstd -d arquivo.out | diff - arquivo.in`.
- **Linkagem estática:** no Linux com musl/static-linking, defina `ZSTLIB_STDIO_LIBS` / `ZSTLIB_STATIC_LINKED=1` nos arquivos-fonte.
- **Se seu `Zlib::` é uma classe C++:** embale estas funções num namespace próprio (ex.: `Zstd`), seguindo o mesmo estilo do seu `NormalUncompress`, e reexporte do jeito que preferir.

Se quiser, posso adaptar essas funções para o formato exato do seu projeto (classe `Zlib::`, protótipos, exceções etc.). É só mandar o código. 😊

