    uint32_t avail = c->dstCap - c->dstPos;
    uint32_t w = 0;
    /* escreve quantos blocos caibam */
    while (w < avail && inLen >= (uint32_t)(avail - w)) {
        size_t sz;
        int r = zstd_compress(c->ctx, p + w, &sz, (const byte*)in, inLen);
        if (r != Z_OK || sz == 0) break; /* parcial/falha */
        w += (uint32_t)sz;
