```c
/**
 * Descompacta dados em zstd (frame completo) para bytes crus.
 * Semelhante a NormalUncompress() do zlib, mas usa zstd.
 *
 * Parâmetros:
 *   dest             – buffer de destino (receberá o dado descomprimido)
 *   destLen          – ponteiro para o TAMANHO ATUAL do buffer (capacidade);
 *                      após a chamada passa a ser o TAMANHO REAL do dado.
 *   source           – dados comprimidos (um frame zstd válido)
 *   sourceLen        – tamanho da source
 *
 * Requisitos: dest precisa ter pelo menos o tamanho estimado de saída;
 * caso contrário a função realoca o buffer internamente (cresce até caber)
 * e ajusta *destLen. Em ambientes sem realloc livre, retorne -1.
 *
 * Retorna: 0 (ok), -1 (erro).
 */
int zstd_uncompress(uint8_t* dest, uint32_t* destLen,
                    const uint8_t* source, uint32_t sourceLen)
{
    if (sourceLen == 0)
        return 0;                              /* entrada vazia => nada a produzir */

    size_t capacity = (size_t)*destLen;
    uint8_t* buf = (uint8_t*)dest;
    uint32_t est = (uint32_t)capacity;

    /* Enquanto não houver espaço suficiente, dobra a capacidade do buffer */
    while ((size_t)est > capacity || capacity < zstd_compress_bound((size_t)sourceLen)) {
        /* Primeiro verifica se realmente precisamos crescer (est > capacity é impossível em teoria,
         * mas serve de guard-rails; o essencial é comparar com o bound). */
        size_t maxNeeded = zstd_compress_bound((size_t)sourceLen);
        if (capacity >= maxNeeded)
            break;                             /* já temos espaço */

        /* Protege contra overflow e crescimento infinito */
        size_t next = capacity + (capacity < ~UINT32_MAX * 4 / 3) ?
                     (size_t)((size_t)capacity * 2) : (size_t)~(size_t)1;
        if (next < capacity)                    /* nunca retroceda */
            break;

        uint8_t* tmp = (uint8_t*)realloc(buf, next);
        if (!tmp) return -1;
        buf = tmp;
        *destLen = next;
        est = (uint32_t)next;
        /* Continua o loop; a próxima tentativa usará o buffer ampliado */
    }

    int ret = zstd_decompress(buf, &est, source, sourceLen);
    if (ret != Z_OK) return -1;

    *destLen = est;
    return 0;
}
```

