Compression context:
```c
typedef struct {
    zstd_compress_ctx* ctx;
    uint8_t* dst;
    uint32_t dstCap;
    uint32_t dstPos;
} zstd_comp_ctx;

static int zstd_comp_init(zstd_comp_ctx* c, uint8_t* dst, uint32_t dstCap, unsigned level)
{
    c->ctx = zstd_create_compress(level);
    if (!c->ctx) return -1;
    c->dst = dst; c->dstCap = dstCap; c->dstPos = 0;
    return 0;
}

static int zstd_comp_writer(zstd_comp_ctx* c, const uint8_t* in, uint32_t inLen)
{
    uint8_t* p = c->dst + c->dstPos;
    uint32_t avail = c->dstCap - c->dstPos;
    uint32_t written = 0;
    uint32_t rem = inLen;

    while (written < avail && rem > 0) {
        uint32_t chunk = (rem < avail - written) ? rem : (avail - written);
        size_t sz;
        int r = zstd_compress(c->ctx, p + written, &sz, (const byte*)in, chunk);
        if (r != Z_OK || sz == 0) break;
        written += (uint32_t)sz;
        p += (uint32_t)sz;
        avail -= (uint32_t)sz;
        rem -= (uint32_t)chunk;          /* ajustamos porque parte pode ter virado > chunk */
        if (written >= avail) break;     /* preencheu o buffer */
    }
