```c
/* ---------- streaming: descompressão ----------
 * Uso incremental, parecido com inflate/inflateEnd (blocos/bytes),
 * ideal para arquivos grandes. Fluxo: ler -> feed -> flush -> finish.
 */

typedef struct {
    zstd_decompress_ctx* dc;
    uint8_t* dst;
    uint32_t dstCap;
    uint32_t dstPos;     /* posição atual dentro do buffer de saída */
} zstd_decomp_ctx_t;

int zstd_decomp_begin(zstd_decomp_ctx_t* d, uint8_t* dst, uint32_t dstCap)
{
    d->dc = zstd_dctx_create(Zstd_compressionLevel_default);
    if (!d->dc) return -1;
    d->dst = dst;
    d->dstCap = dstCap;
    d->dstPos = 0;
    return 0;
}

/* Devolve quantos bytes da src conseguimos consumir neste lote
 * e grava a correspondente fatia em dst[pos].
 */
size_t zstd_decomp_feed(zstd_decomp_ctx_t* d,
                        const uint8_t* src, uint32_t srcLen)
{
    uint8_t* p = d->dst + d->dstPos;
    uint32_t avail = d->dstCap - d->dstPos;
    uint32_t inRem = srcLen;
    size_t written = 0;

    while (avail > 0 && inRem > 0) {
        uint32_t chunk;
        if (inRem <= avail) chunk = (uint32_t)inRem;
        else chunk = avail;

        /* NOTE: zstd_dctx_read escreve no máximo `dstLen` bytes em dst */
        size_t len;
        int r = zstd_dctx_read(d->dc, p + written, &len, src, chunk);
        if (r != Z_OK) break;                 /* erro ou precisa de mais */
        written += (size_t)len;
        p += (uint32_t)len;
        avail -= (uint32_t)len;
        inRem -= (uint32_t)chunk;
        if (written >= avail) break;          /* buffer cheio */
    }
    return written;
}

static int zstd_decomp_finish(zstd_decomp_ctx_t* d, uint8_t** dstOut,
                             uint32_t* dstLen)
{
    uint8_t* p = d->dst + d->dstPos;
    uint32_t avail = d->dstCap - d->dstPos;
    size_t len;

    /* 1) força qualquer bloco pendente interno para fora */
    int r = zstd_dctx_flush(d->dc, p, &len);
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;
    /* Z_BUF_ERROR aqui = precisa de mais espaço; o chaman deveriam crescer. */
    p += (uint32_t)len; avail -= (uint32_t)len;

    /* 2) finaliza: retorna Z_STREAM_END quando tudo foi descompactado */
    r = zstd_dctx_finish(d->dc, p, &len);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *dstOut = d->dst;  /* base do buffer */
    *dstLen = (uint32_t)(p - d->dst);
    return 0;
}
```

