                    ? (size_t)((size_t)capacity * 2 + 1)
                    : MAX_OUT.capacity_limit;
        if (nxt <= capacity) break; /* limite de segurança */
        uint8_t* tmp = (uint8_t*)realloc((uint8_t*)dest, nxt);
        if (!tmp) return -1;
        dest = tmp;
