```c
/* Streaming de compressão (esqueleto ilustrativo — confira
   as assinaturas de contexto em zstd.h da sua versão, pois
   elas variam entre libzstd 0.7 e 0.19).
 */
typedef struct {
    zstd_compress_ctx* ctx;
    uint8_t* dst;
    uint32_t dstCap;
    uint32_t pos;
} zstd_comp_ctx_t;

static int zstd_comp_start(zstd_comp_ctx_t* c, uint8_t* dst, uint32_t dstCap, unsigned level)
{
    c->ctx = zstd_create_compress(level);
    if (!c->ctx) return -1;
    c->dst = dst; c->dstCap = dstCap; c->pos = 0;
    int r = zstd_cctx_start_compress(c->ctx, dst, dstCap, 0); /* flag padrão */
    if (r != Z_OK && r != Z_BUF_ERROR) { /* erro de inicialização */ ... }
    return 0;
}

static int zstd_comp_writer(zstd_comp_ctx_t* c, const uint8_t* in, uint32_t inLen)
{
    uint8_t* p = c->dst + c->pos;
    uint32_t avail = c->dstCap - c->pos;
    uint32_t written = 0;
    size_t remaining = (size_t)inLen;

    while (written < avail && remaining > 0) {
        uint32_t chunk = remaining < avail - written ? remaining : (avail - written);
        size_t sz;
        int r = zstd_cctx_compress(c->ctx, p + written, &sz, (const byte*)in, chunk, 0);
        if (r != Z_OK || sz == 0) break;   /* fim/necessidade de mais espaço */
        written += (uint32_t)sz;
        p += (uint32_t)sz;
        avail -= (uint32_t)sz;
        remaining -= chunk;                  /* avança a fonte de entrada */
        if (written >= avail) break;
    }
    return written;
}

static int zstd_comp_end(zstd_comp_ctx_t* c, uint8_t** outBase, uint32_t* outLen)
{
    uint8_t* p = c->dst + c->pos;
    uint32_t avail = c->dstCap - c->pos;
    size_t sz;

    /* 1) flush do último bloco pendente (e demais buffers internos) */
    int r = zstd_cctx_flush(c->ctx, p, &sz);
    if (r != Z_OK && r != Z_BUF_ERROR) { /* não deu para drenar: mais memória? */
        // se Z_BUF_ERROR: crescer o buffer e tentar de novo
        return -1;
    }
    p += (uint32_t)sz; avail -= (uint32_t)sz;

    /* 2) finalização: Z_STREAM_END indica sucesso total */
    r = zstd_cctx_finish(c->ctx, p, &sz);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *outBase = c->dst;
    *outLen = (uint32_t)(p - c->dst);  /* incluir o que o flush/finish escreveu */
    return 0;
}

void zstd_comp_destroy(zstd_comp_ctx_t* c) { zstd_cctx_destroy(c->ctx); }
```

