Boa pergunta! A API do zstd é independente da do zlib, então não é uma questão de "converter inflate em algo": você troca pelas funções equivalentes do libzstd. As principais são:

- **`zstd_decompress`** — equivalente funcional à sua `inflate()` (descompactar)
- **`zstd_compress`** — equivalente à compressão
- **`zstd_compress_bound(n)`** — retorna um teto teórico pro tamanho da saída (útil pra pré-alocar memória)

Detalhe importante: o zlib trabalha com stream deflate "raw"; o zstd trabalha com **frames completos** (tem número mágico, flags, CRC, tabelas FSE etc.), então `zstd_decompress` já lê e valida o frame sozinho.

Segue uma adaptação linha a linha do seu código.

## 1) Descompactação (equivalente à `NormalUncompress`)

### 1a. Versão simples (só funciona se `dest` já tiver espaço suficiente)

```c
int zstd_uncompress_uint(uint8_t* dest, uint32_t* destLen,
                         const uint8_t* src, uint32_t srcLen,
                         unsigned level)
{
    if (srcLen == 0) return 0;                          /* entrada vazia => nada a produzir */
    uint32_t est;
    int r = zstd_decompress(dest, &est, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;                          /* Z_BUF_ERROR = pouco espaço; Z_ERROR = dado inválido */
    *destLen = est;                                    /* est agora tem o tamanho real descomprimido */
    return 0;
}
```

(Assinatura atual da API: `int zstd_decompress(void* dst, uint32_t* dstSizeEst, const byte* src, uint32_t srcSize, unsigned level, zstd_common_flags flags);` — confira no seu `zstd.h`.)

### 1b. Versão robusta (cresce o buffer automaticamente — recomendada)

```c
#define MAX_OUT_EXPAND ((size_t)1 << 26)  /* 64 MiB; ajuste se necessário */

int zstd_uncompress_auto(uint8_t* dest, uint32_t* destLen,
                         const uint8_t* src, uint32_t srcLen,
                         unsigned level)
{
    if (srcLen == 0) return 0;

    size_t maxOut = zstd_compress_bound((size_t)srcLen);   /* teto teórico da saída */
    size_t cap    = (size_t)*destLen;
    uint8_t* buf  = (uint8_t*)dest;
    uint32_t est  = (uint32_t)cap;

    /* Dobra o buffer até caber (salta direto para maxOut se a estimativa indicar déficit grande) */
    while (cap < maxOut) {
        size_t nxt;
        if (cap < maxOut / 2)
            nxt = maxOut;                                  /* prever que precisa de quase tudo */
        else
            nxt = (size_t)((size_t)cap * 2 + 1);          /* crescimento exponencial */
        if (nxt <= cap) break;                             /* proteção contra overflow */
        uint8_t* tmp = (uint8_t*)realloc(buf, nxt);
        if (!tmp) return -1;
        buf = tmp;
        *destLen = (uint32_t)nxt;
        cap     = nxt;
        est     = (uint32_t)cap;
    }

    uint32_t outLen;
    int r = zstd_decompress(buf, &outLen, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;

    *destLen = outLen;
    return 0;
}
```

Obs.: cuidado com `*destLen == 0` — tanto o inflate do zlib quanto o zstd reclamam de buffer sem espaço (no zlib, inclusive, chamar com `avail_out == 0` retorna `Z_OK` mas SEM produzir saída nenhuma).

## 2) Compressão (novas funções, espelhando as de descompressão)

### 2a. Versão simples

```c
int zstd_compress_uint(uint8_t* dest, uint32_t* destLen,
                       const uint8_t* src, uint32_t srcLen,
                       unsigned level)
{
    if (srcLen == 0) {
        /* entrada vazia ainda gera um frame (cabeçalho + tabelas); a API escreve o tamanho real */
        uint32_t est;
        int r = zstd_compress(dest, &est, NULL, 0, level, ZSTD_COMMON_FLAGS_DEFAULT);
        if (r != Z_OK) return -1;
        *destLen = est;
        return 0;
    }
    size_t bound = zstd_compress_bound((size_t)srcLen);
    if ((size_t)*destLen < bound) return -1;   /* sem espaço livre suficiente */
    uint32_t est = (uint32_t)*destLen;
    int r = zstd_compress(dest, &est, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;
    *destLen = est;
    return 0;
}
```

### 2b. Versão com expansão automática

```c
int zstd_compress_auto(uint8_t* dest, uint32_t* destLen,
                       const uint8_t* src, uint32_t srcLen,
                       unsigned level)
{
    if (srcLen == 0) {
        /* caso vazio: uma chamada resolve (mesmo raciocínio acima) */
        uint32_t est;
        int r = zstd_compress(dest, &est, NULL, 0, level, ZSTD_COMMON_FLAGS_DEFAULT);
        if (r != Z_OK) return -1;
        *destLen = est;
        return 0;
    }

    size_t bound = zstd_compress_bound((size_t)srcLen);
    size_t cap   = (size_t)*destLen;
    uint8_t* buf = (uint8_t*)dest;
    uint32_t est = (uint32_t)cap;

    while (cap < bound) {
        size_t nxt;
        if (cap < bound / 2) nxt = bound;                /* salto para o tamanho estimado */
        else                  nxt = (size_t)((size_t)cap * 2 + 1);
        if (nxt <= cap) break;                            /* proteção contra overflow */
        uint8_t* tmp = (uint8_t*)realloc(buf, nxt);
        if (!tmp) return -1;
        buf = tmp; *destLen = (uint32_t)nxt; cap = nxt; est = (uint32_t)cap;
    }

    int r = zstd_compress(buf, &est, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r == Z_BUF_ERROR) return -1;   /* ainda sem espaço (improvável após o crescimento) */
    if (r != Z_OK) return -1;

    *destLen = est;
    return 0;
}
```

## 3) Streaming incremental (para arquivos grandes / cópia em tempo real)

Quando você não quer esperar o arquivo inteiro na RAM nem depende do tamanho total ser conhecido de antemão, usa os **contextos**: `zstd_decompress_ctx` e `zstd_compress_ctx`. Ideia: alimentar blocos → ler/escrever pedaços → flush → finalizar.

Descompressão (exemplo baseado em `zstd_dctx_*`, libzstd 0.18+):

```c
typedef struct {
    zstd_decompress_ctx* dc;
    uint8_t* dst;
    uint32_t cap;
    size_t pos;      /* offset de leitura dentro do buffer de saída */
} zstd_decomp_ctx;

static int zstd_decomp_init(zstd_decomp_ctx* d,
                            const uint8_t* firstBlock,   /* primeiros bytes válidos */
                            uint32_t firstBlockSize,     /* tamanho desse primeiro bloco */
                            uint8_t* dst, uint32_t cap)
{
    d->dc = zstd_dctx_create(Zstd_compressionLevel_default);
    if (!d->dc) return -1;
    int r = zstd_dctx_start_decompress(d->dc, firstBlock, firstBlockSize);
    if (r != Z_OK) { zstd_dctx_destroy(d->dc); return -1; }
    d->dst = dst; d->cap = cap; d->pos = 0;
    return 0;
}

size_t zstd_decomp_fill(zstd_decomp_ctx* d,
                        const uint8_t* src, size_t srcLen)
{
    uint8_t* p = d->dst + d->pos;
    uint32_t avail = d->cap - d->pos;
    size_t written = 0;
    size_t remaining = srcLen;

    while (written < avail && remaining > 0) {
        uint32_t chunk = remaining < avail ? remaining : (uint32_t)avail;
        size_t len;
        int r = zstd_dctx_read(d->dc, p + written, &len, src, chunk);
        if (r != Z_OK) break;            /* erro (procure tratamento) */
        written += len;
        p += (uint32_t)len;
        avail  -= (uint32_t)len;
        remaining -= chunk;
        if (written >= avail) break;
    }
    return written;
}

static int zstd_decomp_finalize(zstd_decomp_ctx* d,
                               uint8_t** out, uint32_t* outLen)
{
    uint8_t* p = d->dst + d->pos;
    size_t len;

    int r = zstd_dctx_flush(d->dc, p, &len);     /* empurra bloco(s) pendente(s) */
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;  /* precisaria de mais memória */
    p += (size_t)len;

    r = zstd_dctx_finish(d->dc, p, &len);       /* finaliza; Z_STREAM_END = sucesso */
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *out = d->dst;
    *outLen = (uint32_t)(p - d->dst);
    return 0;
}

void zstd_decomp_destroy(zstd_decomp_ctx* d) { zstd_dctx_destroy(d->dc); }
```

Para compressão em fluxo, o esquema é espelhado (criar `zstd_compress_ctx`, `zstd_cctx_start_compress`, escrever blocos com `zstd_cctx_compress`, `zstd_cctx_flush`, `zstd_cctx_finish`) — **confirme as assinaturas exatas no arquivo `zstd.h` da sua build**, pois elas variam um pouco entre versões.

## 4) Dicas práticas

- **Pré-alocação:** `zstd_compress_bound(N)` dá um limite superior garantido → ideal para abrir arquivos com tamanho conhecido.
- **Erros comuns:** `Z_BUF_ERROR` = falta de espaço no buffer; `Z_ERROR`/`Z_DATA_ERROR` = frame corrompido/inválido. Trate separadamente.
- **Teste rápido:** gere com `zstd -tc file.in` (modo texto) e valide com `zstd --test file.out` ou `zstd -d file.out | diff`.
- **Memória:** as funções one-shot escrevem DENTRO do buffer fornecido; garanta que `*destLen ≥` estimativa, senão há erro (ou use as versões com expansão automática).
- **Nível de compressão:** passe `Zstd_compressionLevel_default` (3) ou ajuste (0 = mais rápido, 7 = melhor relação). Você pode também usar níveis personalizados combinando flags (ex.: fast + dict).
- **Frame x raw:** o resultado de `zstd_compress` é sempre um frame válido; `zstd_decompress` lê e valida automaticamente. Formato "bruto" (sem frame/cabeçalho) exige APIs específicas — não é o caminho do one-shot.

