/* ==================== Streaming (uso incremental) ==================== */
/* Libzstd 0.18+: zstd_dctx_* (descompressão) e zstd_cctx_* (compressão).
 * Confira as assinaturas exatas em zstd.h — elas variam levemente
 * entre versões; o fluxo abaixo é o padrão da biblioteca. */

typedef struct {
    zstd_decompress_ctx* dc;
    uint8_t* dst;
    size_t cap;
    size_t pos;           /* offset no buffer de saída */
} zstd_decomp_ctx_t;

/* Inicializa o contexto com um pedaço inicial de dados (para validar o frame).
 * Se você já sabe o tamanho do primeiro bloco, passe-o; senão, um buffer
 * grande o suficiente serve — o contexto consome até o fim do primeiro bloco. */
static int zstd_decomp_new(zstd_decomp_ctx_t* d,
                           const uint8_t* first, uint32_t firstLen,
                           uint8_t* dst, size_t cap)
{
    d->dc = zstd_dctx_create(Zstd_compressionLevel_default);
    if (!d->dc) return -1;
    int r = zstd_dctx_start_decompress(d->dc, first, firstLen);
    if (r != Z_OK) { zstd_dctx_destroy(d->dc); return -1; }
    d->dst = dst; d->cap = cap; d->pos = 0;
    return 0;
}

/* Puxa da fonte o máximo de bytes que caber no buffer de saída atual.
 * Avance a fonte de acordo com `written` nas próximas iterações. */
size_t zstd_decomp_next(zstd_decomp_ctx_t* d,
                        const uint8_t* src, size_t srcLen,
                        uint8_t* out, size_t outCap)
{
    uint8_t* p = d->dst + d->pos;
    uint32_t avail = (uint32_t)outCap - d->pos;
    size_t inRem = srcLen;
    size_t written = 0;

    while (written < avail && inRem > 0) {
        uint32_t chunk;
        if (inRem <= (uint32_t)avail) chunk = (uint32_t)inRem;
        else chunk = avail;

        size_t len;
        int r = zstd_dctx_read(d->dc, p + written, &len, src, chunk);
        if (r != Z_OK) break;                  /* erro: trate e saia */
        written += len;
        p += (uint32_t)len;
        avail -= (uint32_t)len;
        inRem -= chunk;
        if (written >= avail) break;
    }
    return written;
}

static int zstd_decomp_finish(zstd_decomp_ctx_t* d, uint8_t** out, uint32_t* outLen)
{
    uint8_t* p = d->dst + d->pos;
    size_t len;

    /* 1º: coloca qualquer bloco pendente interno para fora */
    int r = zstd_dctx_flush(d->dc, p, &len);
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;   /* precisaria de mais memória */
    p += (size_t)len;

    /* 2º: termina; Z_STREAM_END significa sucesso total */
    r = zstd_dctx_finish(d->dc, p, &len);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *out = d->dst;
    *outLen = (uint32_t)(p - d->dst);
    return 0;
}

void zstd_decomp_destroy(zstd_decomp_ctx_t* d) { zstd_dctx_destroy(d->dc); }
