/* Compressão em fluxo (esqueleto — confira assinaturas em zstd.h) */

typedef struct {
    zstd_compress_ctx* ctx;
    uint8_t* dst;
    size_t cap;
    size_t pos;
} zstd_comp_ctx_t;

static int zstd_comp_new(zstd_comp_ctx_t* c, uint8_t* dst, size_t cap, unsigned level)
{
    c->ctx = zstd_create_compress(level);
    if (!c->ctx) return -1;
    /* começa a compressão com espaço inicial reservado */
    int r = zstd_cctx_start_compress(c->ctx, dst, cap, 0);  /* 0 = flags padrão */
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;
    c->dst = dst; c->cap = cap; c->pos = 0;
    return 0;
}

size_t zstd_comp_write(zstd_comp_ctx_t* c, const uint8_t* in, size_t inLen)
{
    uint8_t* p = c->dst + c->pos;
    uint32_t avail = (uint32_t)(c->cap - c->pos);
    size_t written = 0;
    size_t inRem = inLen;
    size_t chunk;

    while (written < avail && inRem > 0) {
        chunk = (inRem < (uint32_t)avail) ? inRem : (uint32_t)avail;
        size_t sz;
        int r = zstd_cctx_compress(c->ctx, p + written, &sz, (const byte*)in, chunk, 0);
        if (r != Z_OK || sz == 0) break;   /* 0 = fim/pediu mais espaço */
        written += sz;
        p += (size_t)sz;
        avail -= (size_t)sz;
        inRem -= chunk;
    }
    return written;
}

static int zstd_comp_finish(zstd_comp_ctx_t* c, uint8_t** out, uint32_t* outLen)
{
    uint8_t* p = c->dst + c->pos;
    size_t len;
    int r;

    r = zstd_cctx_flush(c->ctx, p, &len);
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;  /* precisa de mais memória */
    p += (size_t)len;

    r = zstd_cctx_finish(c->ctx, p, &len);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *out = c->dst;
    *outLen = (uint32_t)(p - c->dst);
    return 0;
}

void zstd_comp_destroy(zstd_comp_ctx_t* c) { zstd_cctx_destroy(c->ctx); }
