/**
 * Equivalente direto da sua NormalUncompress(), porém com zstd.
 * Requer que `dest` já tenha espaço suficiente; caso contrário retorne Z_BUF_ERROR
 * (por isso existe a versão "auto" logo abaixo).
 */
int uncompress_zstd(uint8_t* dest, uint32_t* destLen,
                    const uint8_t* src, uint32_t srcLen,
                    unsigned level)
{
    if (srcLen == 0) return 0;

    uint32_t est;
    int r = zstd_decompress(dest, &est, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;   /* Z_BUF_ERROR = pouco espaço; Z_ERROR = entrada inválida */

    *destLen = est;             /* `est` passa a conter o tamanho real descomprimido */
    return 0;
}
