#define BUFFER_EXPAND_LIMIT ((size_t)64 * 1024 * 1024)  /* 64 MiB; aumente se precisar */

int uncompress_zstd_auto(uint8_t* dest, uint32_t* destLen,
                        const uint8_t* src, uint32_t srcLen,
                        unsigned level)
{
    if (srcLen == 0) return 0;

    size_t maxOut = zstd_compress_bound((size_t)srcLen);   /* teto garantido da saída */
    size_t cap    = (size_t)*destLen;
    uint8_t* buf  = (uint8_t*)dest;
    uint32_t est  = (uint32_t)cap;

    while (cap < maxOut) {
        size_t nxt;
        if (cap < maxOut / 2)         nxt = maxOut;          /* estima que vai precisar de quase tudo */
        else                          nxt = (size_t)((size_t)cap * 2 + 1); /* crescimento exponencial */
        if (nxt <= cap) break;       /* proteção contra overflow */
        uint8_t* tmp = (uint8_t*)realloc((uint8_t*)dest, nxt);
        if (!tmp) return -1;
        buf    = tmp;
        *destLen = (uint32_t)nxt;
        cap     = nxt;
        est     = (uint32_t)cap;    /* retenta agora com o buffer maior */
    }

    uint32_t outLen;
    int r = zstd_decompress(buf, &outLen, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;

    *destLen = outLen;
    return 0;
}
