/**
 * Equivalente de "deflate" usando zstd.
 * Como o zstd trabalha com frames, a saída já é um objeto zstd válido
 * (cabeçalho + compressão + checagens). Guarde os `bound()` para pré-alocar.
 */
int compress_zstd(uint8_t* dest, uint32_t* destLen,
                  const uint8_t* src, uint32_t srcLen,
                  unsigned level)
{
    if (srcLen == 0) {
        /* entrada vazia ainda gera um frame mínimo; a própria API escreve o tamanho */
        uint32_t est;
        int r = zstd_compress(dest, &est, NULL, 0, level, ZSTD_COMMON_FLAGS_DEFAULT);
        if (r != Z_OK) return -1;
        *destLen = est;
        return 0;
    }

    size_t bound = zstd_compress_bound((size_t)srcLen);
    if ((size_t)*destLen < bound) return -1;   /* sem espaço suficiente */

    uint32_t est = (uint32_t)*destLen;
    int r = zstd_compress(dest, &est, src, srcLen, level, ZSTD_COMMON_FLAGS_DEFAULT);
    if (r != Z_OK) return -1;

    *destLen = est;
    return 0;
}
