/* Esqueleto de compressão em fluxo (compress context) — as assinaturas
   das funções zstd_cctx_* variam levemente entre versões; confira em zstd.h. */

typedef struct {
    zstd_compress_ctx* ctx;
    uint8_t* dst;
    size_t cap;
    size_t pos;
} zstd_comp_ctx_t;

static int zstd_comp_new(zstd_comp_ctx_t* c, uint8_t* dst, size_t cap, unsigned level)
{
    c->ctx = zstd_create_compress(level);
    if (!c->ctx) return -1;
    int r = zstd_cctx_start_compress(c->ctx, dst, cap, 0);  /* 0 = flags padrão */
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;
    c->dst = dst; c->cap = cap; c->pos = 0;
    return 0;
}

static int zstd_comp_write(zstd_comp_ctx_t* c, const uint8_t* src, size_t srcLen,
                           size_t* totalOut)
{
    size_t written = 0;
    size_t pos     = 0;
    size_t remaining = srcLen;
    uint32_t chunk;
    size_t sz;
    int r;

    while (pos < remaining) {
        chunk = (uint32_t)min(remaining - pos, 65536U);
        r = zstd_cctx_compress(c->ctx, c->dst + written, &sz,
                               src + (size_t)pos, chunk, 0);
        if (r == Z_OK) {
            written += (size_t)sz;
            pos += chunk;              /* avança a fonte por inteiro; o contexto continua */
        }
        else if (r == Z_BUF_ERROR)    /* não coube: cresça o buffer e repita */ return -1;
        else                          return -1;
    }

    /* finalizar: empurra o último bloco e fecha o frame */
    sz;
    r = zstd_cctx_flush(c->ctx, c->dst + written, &sz);
    if (r != Z_OK && r != Z_BUF_ERROR) return -1;
    written += (size_t)sz;

    r = zstd_cctx_finish(c->ctx, c->dst + written, &sz);
    if (r != Z_OK && r != Z_STREAM_END) return -1;

    *totalOut = written;
    return 0;
}

void zstd_comp_destroy(zstd_comp_ctx_t* c) { zstd_cctx_destroy(c->ctx); }
