const express = require('express');
const { SessionContextClient } = require('@google-cloud/dialogflow');

const app = express();
app.use(express.json());

const PROJECT_ID = process.env.DIALOGFLOW_PROJECT_ID;
const AGENT_ID = process.env.DIALOGFLOW_AGENT_ID;

// Respostas por intenção
const MAPA_RESPOSTAS = {
  'saudeacao': 'Olá! Seja bem-vindo ao nosso atendimento. Posso ajudar com informações sobre preços, horários ou agendamento?',
  'dubiahorario': 'Atendemos de segunda a sexta-feira, das 9h às 18h. Aos sábados, das 9h às 13h.',
  'faleconosco': 'Claro! Por favor, informe seu nome completo e um contato (telefone ou e-mail) para prosseguirmos.',
  'DEFAULT_INTENT': 'Desculpe, não entendi. Tente reformular sua pergunta ou escolha outra opção.'
};

app.post('/webhook', async (req, res) => {
  try {
    const { transcripts } = req.body;
    if (!transcripts || transcripts.length === 0) {
      return res.status(200).json({ sessionId: req.body.sessionId, nextAction: {} });
    }

    const session = await new SessionContextClient().getSessionContext({
      projectId: PROJECT_ID,
      sessionId: transcripts[0].sessionId
    });

    const ultimaMensagem = transcripts[0].messages[transcripts[0].messages.length - 1];
    let intentId = 'DEFAULT_INTENT';

    if (ultimaMensagem.intent && ultimaMensagem.intent.detectedIntent) {
      intentId = ultimaMensagem.intent.detectedIntent.intentId;
    }

    const resposta = MAPA_RESPOSTAS[intentId] || MAPA_RESPOSTAS['DEFAULT_INTENT'];

    // Enviar resposta usando o contexto da sessão
    const mensagensResposta = await new SessionContextClient().sendSessionUpdates({
      projectId: PROJECT_ID,
      sessionId: transcripts[0].sessionId,
      response: {
        messages: [{
          content: resposta,
          sourceLanguage: 'pt-BR'
        }]
      }
    });

    res.status(200).json({
      sessionId: transcripts[0].sessionId,
      response: {
        messages: mensagensResposta.map(msg => ({
          content: msg.content,
          sourceLanguage: msg.sourceLanguage
        }))
      }
    });
  } catch (err) {
    console.error('Erro no webhook:', err);
    res.status(500).json({ error: 'Falha interna no servidor' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Webhook do Dialogflow ativo na porta ${PORT}`);
});
